/**
 * ۲) نگاشت اسلاگ دسته به نام فارسی (برای ساخت دسته در صورت نبود).
 */
function qpai_cat_map() {
	return array(
		'fundamentals'        => 'مبانی و مفاهیم کوانتوم',
		'core-concepts'       => 'مفاهیم پایه',
		'particles'           => 'ذرات بنیادی',
		'history-experiments' => 'تاریخ و آزمایش‌های کوانتوم',
		'history'             => 'تاریخ کوانتوم',
		'experiments'         => 'آزمایش‌های کوانتومی',
		'phenomena'           => 'پدیده‌های کوانتومی',
		'mathematics'         => 'ریاضیات و فرمالیسم کوانتومی',
		'technology'          => 'فناوری و کاربردهای کوانتومی',
		'everyday-tech'       => 'فناوری‌های روزمره',
		'quantum-computing'   => 'رایانش و ارتباطات کوانتومی',
		'quantum-biology'     => 'زیست‌شناسی کوانتومی',
		'interpretations'     => 'تفسیرها و فلسفهٔ کوانتوم',
		'pseudoscience'       => 'نقد شبه‌علم',
	);
}

/**
 * ۳) برگرداندن شناسهٔ دسته در quantum_category (ساخت در صورت نبود).
 */
function qpai_term_id( $slug ) {
	$slug = sanitize_title( $slug );
	if ( '' === $slug ) { return 0; }
	$term = get_term_by( 'slug', $slug, 'quantum_category' );
	if ( $term && ! is_wp_error( $term ) ) {
		return (int) $term->term_id;
	}
	$map  = qpai_cat_map();
	$name = isset( $map[ $slug ] ) ? $map[ $slug ] : $slug;
	$r    = wp_insert_term( $name, 'quantum_category', array( 'slug' => $slug ) );
	if ( is_wp_error( $r ) ) {
		$data = $r->get_error_data();
		if ( isset( $data['term_exists'] ) ) {
			return (int) $data['term_exists'];
		}
		return 0;
	}
	return (int) $r['term_id'];
}

/**
 * ۴) پیدا کردن شناسهٔ کاربر برای نویسنده؛ در نبود، کاربر جاری یا ۱.
 */
function qpai_author_id( $name ) {
	$name = trim( (string) $name );
	if ( '' !== $name ) {
		$slugs   = array();
		$slugs[] = sanitize_title( $name );
		$slugs[] = str_replace( '-', '', sanitize_title( $name ) );
		foreach ( $slugs as $s ) {
			if ( '' === $s ) { continue; }
			$u = get_user_by( 'slug', $s );
			if ( $u ) { return (int) $u->ID; }
			$u = get_user_by( 'login', $s );
			if ( $u ) { return (int) $u->ID; }
		}
		$users = get_users( array( 'search' => '*' . $name . '*', 'number' => 1 ) );
		if ( ! empty( $users ) ) { return (int) $users[0]->ID; }
	}
	$current = get_current_user_id();
	return $current ? $current : 1;
}

/**
 * ۵) صفحهٔ ابزار.
 */
add_action( 'admin_menu', 'qpai_admin_menu' );
function qpai_admin_menu() {
	add_management_page( 'ورود مقالات کیوپدیا', 'ورود مقالات کیوپدیا', 'edit_posts', 'qpai', 'qpai_screen' );
}

function qpai_screen() {
	if ( ! current_user_can( 'edit_posts' ) ) { wp_die( 'دسترسی ندارید.' ); }
	$items = qpai_payload();

	echo '<div class="wrap" dir="rtl"><h1>ورود مقالات کیوپدیا</h1>';
	echo '<p>' . count( $items ) . ' مقاله از ۵ بسته، آمادهٔ ورود به‌صورت <strong>پیش‌نویس</strong> در «مقالات کوانتوم» (quantum_article).</p>';

	if ( isset( $_POST['qpai_go'] ) && check_admin_referer( 'qpai_run' ) ) {
		$new = 0; $upd = 0; $err = 0; $skip = 0;
		echo '<div class="notice notice-info"><ul>';
		foreach ( $items as $it ) {
			$slug    = isset( $it['slug'] ) ? sanitize_title( $it['slug'] ) : '';
			$title   = isset( $it['title'] ) ? $it['title'] : '';
			$content = isset( $it['content'] ) ? $it['content'] : '';
			$excerpt = isset( $it['excerpt'] ) ? $it['excerpt'] : '';

			$existing = get_posts(
				array(
					'post_type'      => 'quantum_article',
					'name'           => $slug,
					'post_status'    => array( 'publish', 'draft', 'pending', 'private', 'future' ),
					'posts_per_page' => 1,
					'fields'         => 'ids',
				)
			);

			$args = array(
				'post_type'    => 'quantum_article',
				'post_title'   => $title,
				'post_name'    => $slug,
				'post_content' => $content,
				'post_excerpt' => $excerpt,
				'post_status'  => 'draft',
				'post_author'  => qpai_author_id( isset( $it['author_en'] ) ? $it['author_en'] : '' ),
			);

			if ( ! empty( $existing ) ) {
				$prev_status = get_post_status( (int) $existing[0] );
				if ( 'publish' === $prev_status ) {
					// مقالهٔ منتشرشده را دست نمی‌زنیم؛ فقط گزارش می‌دهیم (جلوگیری از بازنویسی محتوای زنده).
					$skip++;
					echo '<li>⚠️ رد شد (قبلاً در سایت منتشر شده) — <a href="' . esc_url( get_edit_post_link( (int) $existing[0] ) ) . '">' . esc_html( $title ) . '</a></li>';
					continue;
				}
				$args['ID'] = (int) $existing[0];
				$id         = wp_update_post( $args );
				$verb       = 'به‌روزرسانی';
				$upd++;
			} else {
				$id   = wp_insert_post( $args );
				$verb = 'ایجاد';
				$new++;
			}

			if ( $id && ! is_wp_error( $id ) ) {
				$term_ids = array();
				if ( ! empty( $it['categories'] ) && is_array( $it['categories'] ) ) {
					foreach ( $it['categories'] as $cslug ) {
						$tid = qpai_term_id( $cslug );
						if ( $tid ) { $term_ids[] = $tid; }
					}
				}
				if ( ! empty( $term_ids ) ) {
					wp_set_object_terms( $id, $term_ids, 'quantum_category' );
				}

				if ( isset( $it['tags'] ) ) { update_post_meta( $id, '_qpedia_tags', $it['tags'] ); }
				if ( isset( $it['seo_title'] ) ) { update_post_meta( $id, '_qpedia_seo_title', $it['seo_title'] ); }
				if ( isset( $it['meta_description'] ) ) { update_post_meta( $id, '_qpedia_meta_description', $it['meta_description'] ); }
				if ( isset( $it['focus_keyphrase'] ) ) { update_post_meta( $id, '_qpedia_focus_keyphrase', $it['focus_keyphrase'] ); }
				if ( isset( $it['secondary_keyphrases'] ) ) { update_post_meta( $id, '_qpedia_secondary_keyphrases', $it['secondary_keyphrases'] ); }
				if ( isset( $it['author_en'] ) ) { update_post_meta( $id, '_qpedia_author_en', $it['author_en'] ); }
				if ( isset( $it['note'] ) ) { update_post_meta( $id, '_qpedia_publish_note', $it['note'] ); }

				echo '<li>✅ ' . esc_html( $verb ) . ' — <a href="' . esc_url( get_edit_post_link( $id ) ) . '">' . esc_html( $title ) . '</a></li>';
			} else {
				$err++;
				echo '<li>❌ ناموفق — ' . esc_html( $title ) . '</li>';
			}
		}
		echo '</ul><p><strong>' . intval( $new ) . ' ایجاد · ' . intval( $upd ) . ' به‌روزرسانی · ' . intval( $skip ) . ' ردشده (منتشر) · ' . intval( $err ) . ' خطا</strong></p></div>';
		echo '<p><a class="button button-primary" href="' . esc_url( admin_url( 'edit.php?post_type=quantum_article&post_status=draft' ) ) . '">دیدن پیش‌نویس‌ها</a></p>';
		echo '<div class="notice notice-warning"><p>ورود تمام شد. پس از بررسی و انتشار مقاله‌ها، <strong>این افزونه را حذف کنید</strong>.</p></div>';
	} else {
		echo '<table class="widefat striped" style="max-width:960px"><thead><tr><th>عنوان</th><th>اسلاگ</th><th>دسته‌ها</th><th>حجم</th><th>وضعیت</th></tr></thead><tbody>';
		foreach ( $items as $it ) {
			$cats = ( isset( $it['categories'] ) && is_array( $it['categories'] ) ) ? implode( '، ', $it['categories'] ) : '';
			$size = isset( $it['content'] ) ? mb_strlen( $it['content'] ) : 0;
			$status = '—';
			$slug   = isset( $it['slug'] ) ? sanitize_title( $it['slug'] ) : '';
			if ( '' !== $slug ) {
				$ex = get_posts(
					array(
						'post_type'      => 'quantum_article',
						'name'           => $slug,
						'post_status'    => array( 'publish', 'draft', 'pending', 'private', 'future' ),
						'posts_per_page' => 1,
						'fields'         => 'ids',
					)
				);
				if ( ! empty( $ex ) ) {
					$status = ( 'publish' === get_post_status( (int) $ex[0] ) ) ? '<span style="color:#b32d2e">⚠ منتشر است</span>' : '<span style="color:#997404">پیش‌نویس موجود</span>';
				}
			}
			echo '<tr><td>' . esc_html( isset( $it['title'] ) ? $it['title'] : '' ) . '</td><td><code>' . esc_html( $slug ) . '</code></td><td>' . esc_html( $cats ) . '</td><td>' . number_format_i18n( $size ) . ' نویسه</td><td>' . $status . '</td></tr>';
		}
		echo '</tbody></table><form method="post" style="margin-top:18px">';
		wp_nonce_field( 'qpai_run' );
		echo '<button name="qpai_go" class="button button-primary button-hero">ورود ۲۰ مقاله به‌صورت پیش‌نویس</button></form>';
		echo '<div class="notice notice-info"><p>نکته: مقاله‌ای که <strong>منتشر شده</strong> باشد هرگز بازنویسی نمی‌شود و رد می‌شود؛ پیش‌نویسِ موجود به‌روزرسانی می‌شود. تگ‌ها و فیلدهای سئو به‌صورت متای سفارشی (<code>_qpedia_*</code>) ذخیره می‌شوند.</p></div>';
	}

	echo '</div>';
}
